from lib import *
S = SS('u170')
R = J('u170'); Y = R['yaml']; G = R['gate']; C = R['cache']; lb = R['lint_bad']
steps = [
    step(f"工作流文件 ci.yml({R['wf_lines']} 行)有四个 job:fmt(cargo fmt --all -- --check)、clippy(cargo clippy --locked --all-targets -- -D warnings)、test(矩阵 os × toolchain,先 cargo build --locked 再 cargo test --locked,还有 cache 步骤)、audit(cargo audit,needs 前三个 job)。触发条件是 push 到 main 与任意 pull_request。本篇没有把它推到 GitHub 运行过。", t=tl(S(1)), done=lidx(S(1), 'cargo fmt --all', 'cargo clippy', 'cargo test --locked', 'cargo audit'), mark=lidx(S(1), 'needs: [fmt, clippy, test]', 'matrix:'), kv=KV([['job', 'fmt、clippy、test、audit'], ['触发', 'push(main)与 pull_request'], ['是否在 GitHub 运行', '没有']], ['是否在 GitHub 运行'])),
    step(f"用 actionlint 1.7.12 静态检查(它只做语法与表达式检查,不运行工作流):ci.yml 退出码 0、没有任何报告。故意写错三处:needs 里写成不存在的 tset → 「job \"audit\" needs job \"tset\" which does not exist in this workflow [job-needs]」;把 matrix.toolchain 写成 matrix.toolchian → 「property \"toolchian\" is not defined in object type {{os: string; toolchain: string}} [expression]」;去掉 fmt 的 runs-on → 「\"runs-on\" section is missing in job \"fmt\" [syntax-check]」,三种都是退出码 1。", t=tl(S(2)), done=lidx(S(2), 'actionlint ci.yml'), mark=lidx(S(2), 'job-needs', 'expression', 'syntax-check'), kv=KV([['正确的 ci.yml', '退出码 0'], ['三处笔误', '都能被查出,退出码 1']], ['三处笔误'])),
    step(f"解析 YAML(PyYAML)与展开矩阵,这是我自己算的,不是 GitHub 的调度结果:test 矩阵 2 个系统 × 2 个工具链 = {Y['combos']} 个 job(ubuntu/stable、ubuntu/beta、macos/stable、macos/beta),加上 fmt、clippy、audit,一次触发共 {Y['total']} 个 job。fail-fast 设为 false:矩阵里一项失败不会取消其它项。audit 声明 needs 前三个 job,只有它们全部成功才会开始。", t=tl(S(3)), done=lidx(S(3), 'test 矩阵', '整个工作流'), mark=lidx(S(3), 'fail-fast'), kv=KV([['矩阵', f"2 × 2 = {Y['combos']} 个 job"], ['总 job 数', str(Y['total'])], ['fail-fast', 'false']], ['总 job 数'])),
    step("在本机按 run: 步骤依次执行(跳过 uses: 步骤与 cargo install,因为本机已有这些工具;test 只执行一个矩阵项,即本机的 macOS + stable;没有执行另外三个矩阵项):fmt、clippy、test、audit 四个 job 全部「通过」。cargo test 的结果行:tests::adds ok、tests::renders ok,2 passed。这只能说明这些命令在本机一个环境里能通过,不等于 GitHub 上的 runner 也会通过。", t=tl(S(4)), done=lidx(S(4), '通过'), kv=KV([['fmt / clippy / test / audit', '本机全部通过'], ['矩阵', '只跑了 1 项(macOS + stable)']], ['矩阵'])),
    step("门禁:每次只注入一个缺陷,看哪个 job 失败。代码没格式化 → 只有 fmt 失败(退出码 1,Diff 显示 -pub fn  add(a:i32,b:i32)->i32{a+b} 与 +pub fn add(a: i32, b: i32) -> i32 {);clippy 的 needless_return → 只有 clippy 失败(-D warnings 把警告变成 error,退出码 101);测试断言写错 → 只有 test 失败(tests::adds ... FAILED,退出码 101);固定带漏洞的 smallvec 1.6.0 → 只有 audit 失败(退出码 1)。每个缺陷只触发对应的那一个 job,说明这几个 job 各管一类问题,互不替代。", t=tl(S(5)), mark=lidx(S(5), '失败'), done=lidx(S(5), '退出码 1;cargo fmt', '退出码 101;cargo clippy', '退出码 101;cargo test', '退出码 1;cargo audit'), kv=KV([['没格式化', '只有 fmt 红'], ['clippy 警告', '只有 clippy 红'], ['断言错', '只有 test 红'], ['漏洞依赖', '只有 audit 红']], ['漏洞依赖'])),
    step("--locked:Cargo.toml 新增了 tinyvec 却没更新 Cargo.lock 时,cargo build --locked 退出码 101:「cannot update the lock file … because --locked was passed to prevent this」。不加 --locked 的 cargo build 退出码 0,但悄悄改写了 Cargo.lock(新增 tinyvec)。所以 CI 里用 --locked 能保证「构建用的正是提交进仓库的锁文件」。", t=tl(S(6)), mark=lidx(S(6), 'cannot update the lock file'), done=lidx(S(6), '不加 --locked'), kv=KV([['cargo build --locked', '退出码 101'], ['cargo build', '退出码 0,改写 Cargo.lock']], ['cargo build --locked'])),
    step(f"缓存的本地对照(用复制 target 目录来模拟 actions/cache,不是在 GitHub 上验证):冷缓存(空 target)cargo test --locked 中位数 {C['cold']:.1f} 秒;恢复缓存后没改动 {C['same']:.2f} 秒;恢复缓存后改了 lib.rs {C['edit']:.2f} 秒。缓存键我用 Cargo.lock 的 sha256 前 12 位近似(GitHub 的 hashFiles 算法与它不同):初始 {C['keys'][0]};改源码后仍是 {C['keys'][1]};新增依赖并重新生成锁文件后变成 {C['keys'][2]},缓存会失效。这个项目很小,绝对时间差别不大,依赖越多越明显。", t=tl(S(7)), b=bars([['冷缓存', C['cold'], f"{C['cold']:.1f} s"], ['恢复缓存,没改动', C['same'], f"{C['same']:.2f} s"], ['恢复缓存,改了 lib.rs', C['edit'], f"{C['edit']:.2f} s"]], C['cold'], done=[0, 1, 2]), kv=KV([['冷缓存', f"{C['cold']:.1f} 秒"], ['恢复缓存后', f"{C['same']:.2f} 秒"], ['缓存键', 'Cargo.lock 变才变']], ['缓存键'])),
]
A = mkart('u170', 170, 'Rust,CI,GitHub Actions,actionlint,cargo,真实验证,动画演示',
    f'为 Rust 项目写一个 GitHub Actions 工作流(fmt / clippy / test 矩阵 / audit)。工作流本身没有在 GitHub 上运行;验证了:actionlint 通过并能查出三种笔误;按 run: 步骤在本机依次执行全部通过;四种缺陷各只让对应的 job 失败;--locked 拒绝过期的 Cargo.lock;缓存的本地模拟。',
    'CI 就是把本地的检查命令放到一个每次提交都会跑的地方。这篇写了一个完整的 ci.yml,然后诚实地区分:哪些是真正验证过的(语法检查、命令本身、门禁行为),哪些只能在 GitHub 上运行才知道(这篇没有做)。',
    [('0 / 1', 'actionlint 对正确 / 笔误的 ci.yml 的退出码'), (f"{Y['total']}", '一次触发的 job 数(2×2 矩阵展开,自己算的)'), ('4 / 4', '注入的 4 种缺陷各只让对应的 1 个 job 失败')],
    [('工作流文件', '<p>本篇串起前面几篇的检查:<a href="rust-rustfmt.html">rustfmt 格式化</a>、<a href="rust-clippy.html">Clippy 静态检查</a>、<a href="rust-unit-integration-tests.html">单元测试与集成测试</a>、<a href="rust-dependency-audit.html">依赖安全审计</a>、<a href="rust-cargo-lock.html">Cargo.lock</a>。</p>'), ('actionlint', None), ('矩阵展开', None), ('本机依次执行', None), ('门禁', None), ('--locked', None), ('缓存', None)],
    steps, [ENV_U + '。actionlint 1.7.12(go install);PyYAML 6.0.2;cargo-audit 0.22.2(RustSec 漏洞库)', '没有验证:工作流在 GitHub Actions 上的真实运行(runner、权限、secrets、并发、超时)、uses: 的第三方 action(actions/checkout@v4、dtolnay/rust-toolchain、actions/cache@v4)的行为、beta 工具链与 ubuntu runner 上的结果、hashFiles 的实际算法、真实缓存的命中与大小限制、其它 CI 系统(GitLab CI 等)', '本机执行时跳过了 uses: 与 cargo install 步骤,test 只跑了一个矩阵项,所以「本机通过」不能代替 CI 的结果'], 'CI')
